import javax.swing.*;
import java.awt.*;

public class FormularioComponentes extends JFrame {

    private JTextField campoNombre, campoEmail, campoEdad;
    private JComboBox<String> comboCiclo;
    private JCheckBox checkNewsletter;
    private JLabel lblResultado;

    public FormularioComponentes() {
        setTitle("Formulario de inscripcion");
        setSize(450, 350);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        // Panel principal
        JPanel principal = new JPanel(new BorderLayout(10, 10));
        principal.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        // Titulo
        JLabel titulo = new JLabel("Formulario de Inscripcion", SwingConstants.CENTER);
        titulo.setFont(new Font("Arial", Font.BOLD, 18));
        principal.add(titulo, BorderLayout.NORTH);

        // Formulario con GridLayout
        JPanel formulario = new JPanel(new GridLayout(5, 2, 5, 10));

        campoNombre = new JTextField();
        campoEmail = new JTextField();
        campoEdad = new JTextField();
        comboCiclo = new JComboBox<>(new String[]{"DAW", "DAM", "ASIR"});
        checkNewsletter = new JCheckBox("Recibir newsletter");

        formulario.add(new JLabel("Nombre:"));
        formulario.add(campoNombre);
        formulario.add(new JLabel("Email:"));
        formulario.add(campoEmail);
        formulario.add(new JLabel("Edad:"));
        formulario.add(campoEdad);
        formulario.add(new JLabel("Ciclo formativo:"));
        formulario.add(comboCiclo);
        formulario.add(new JLabel(""));
        formulario.add(checkNewsletter);

        principal.add(formulario, BorderLayout.CENTER);

        // Resultado y boton
        JPanel sur = new JPanel(new BorderLayout());
        lblResultado = new JLabel(" ", SwingConstants.CENTER);
        lblResultado.setForeground(new Color(0, 100, 0));
        sur.add(lblResultado, BorderLayout.CENTER);

        JButton btnRegistrar = new JButton("Registrar");
        btnRegistrar.addActionListener(e -> registrar());
        JPanel panelBoton = new JPanel();
        panelBoton.add(btnRegistrar);
        sur.add(panelBoton, BorderLayout.SOUTH);

        principal.add(sur, BorderLayout.SOUTH);

        add(principal);
    }

    private void registrar() {
        String nombre = campoNombre.getText().trim();
        String email = campoEmail.getText().trim();
        String edad = campoEdad.getText().trim();
        String ciclo = (String) comboCiclo.getSelectedItem();
        boolean newsletter = checkNewsletter.isSelected();

        if (nombre.isEmpty() || email.isEmpty()) {
            lblResultado.setForeground(Color.RED);
            lblResultado.setText("Error: nombre y email son obligatorios.");
            return;
        }

        lblResultado.setForeground(new Color(0, 100, 0));
        lblResultado.setText("Registrado: " + nombre + " | " + email
            + " | Edad: " + edad + " | Ciclo: " + ciclo
            + (newsletter ? " | Newsletter: si" : ""));
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new FormularioComponentes().setVisible(true));
    }
}

