import javax.swing.*;
import java.awt.*;

public class CalculadoraBasica extends JFrame {
    private JTextField campo1, campo2;
    private JComboBox<String> comboOp;
    private JLabel resultado;

    public CalculadoraBasica() {
        setTitle("Calculadora");
        setSize(300, 200);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        JPanel panel = new JPanel(new GridLayout(4, 2, 5, 5));
        panel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        campo1 = new JTextField();
        campo2 = new JTextField();
        comboOp = new JComboBox<>(new String[]{"+", "-", "*", "/"});
        resultado = new JLabel("Resultado: ");

        panel.add(new JLabel("Numero 1:"));
        panel.add(campo1);
        panel.add(new JLabel("Operacion:"));
        panel.add(comboOp);
        panel.add(new JLabel("Numero 2:"));
        panel.add(campo2);
        panel.add(new JButton("Calcular"));
        panel.add(resultado);

        ((JButton) panel.getComponent(6)).addActionListener(e -> calcular());
        add(panel);
    }

    private void calcular() {
        try {
            double a = Double.parseDouble(campo1.getText());
            double b = Double.parseDouble(campo2.getText());
            String op = (String) comboOp.getSelectedItem();
            double res = switch (op) {
                case "+" -> a + b;
                case "-" -> a - b;
                case "*" -> a * b;
                case "/" -> b != 0 ? a / b : Double.NaN;
                default -> 0;
            };
            resultado.setText("Resultado: " + res);
        } catch (NumberFormatException ex) {
            resultado.setText("Error: introduce numeros validos");
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new CalculadoraBasica().setVisible(true));
    }
}

