import javax.swing.*;
import java.awt.event.*;

public class EjemploEventos extends JFrame {

    private int contador = 0;
    private JLabel lblContador;

    public EjemploEventos() {
        setTitle("Ejemplo de Eventos");
        setSize(300, 200);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        JPanel panel = new JPanel();
        lblContador = new JLabel("Contador: 0");
        panel.add(lblContador);

        // FORMA 1: Clase anonima
        JButton btnAnonima = new JButton("Clase anonima");
        btnAnonima.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                contador++;
                lblContador.setText("Contador: " + contador);
            }
        });
        panel.add(btnAnonima);

        // FORMA 2: Lambda (recomendada)
        JButton btnLambda = new JButton("Lambda");
        btnLambda.addActionListener(e -> {
            contador++;
            lblContador.setText("Contador: " + contador);
        });
        panel.add(btnLambda);

        // FORMA 3: Referencia a metodo
        JButton btnReferencia = new JButton("Referencia");
        btnReferencia.addActionListener(this::incrementar);
        panel.add(btnReferencia);

        add(panel);
    }

    private void incrementar(ActionEvent e) {
        contador++;
        lblContador.setText("Contador: " + contador);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new EjemploEventos().setVisible(true));
    }
}

// Las tres formas son equivalentes:
// 1. Clase anonima: verbose pero explicita
// 2. Lambda: concisa y moderna (recomendada)
// 3. Referencia a metodo: cuando el metodo ya existe y tiene la firma correcta

### MouseListener - Eventos del raton
```java
component.addMouseListener(new MouseAdapter() {
    @Override
    public void mouseClicked(MouseEvent e) {
        System.out.println("Click en: " + e.getX() + ", " + e.getY());
    }
    @Override
    public void mouseEntered(MouseEvent e) { /* cursor entra */ }
    @Override
    public void mouseExited(MouseEvent e) { /* cursor sale */ }
});
```

### KeyListener - Eventos de teclado
```java
campo.addKeyListener(new KeyAdapter() {
    @Override
    public void keyReleased(KeyEvent e) {
        System.out.println("Tecla: " + e.getKeyChar());
    }
});
```

### DocumentListener - Cambios en JTextField/JTextArea
```java
campo.getDocument().addDocumentListener(new DocumentListener() {
    @Override
    public void insertUpdate(DocumentEvent e) { /* texto insertado */ }
    @Override
    public void removeUpdate(DocumentEvent e) { /* texto eliminado */ }
    @Override
    public void changedUpdate(DocumentEvent e) { /* atributo cambiado */ }
});
```

**Cuando usar cada uno:**
- `ActionListener`: botones, campos de texto al pulsar Enter
- `MouseListener`: clicks, movimientos del raton
- `KeyListener`: pulsaciones de tecla en tiempo real
- `DocumentListener`: cambios en el contenido de un campo

import javax.swing.*;
import javax.swing.event.*;
import java.awt.*;

public class ValidacionTiempoReal extends JFrame {

    private JTextField campoEmail;
    private JLabel lblEstado;
    private JButton btnEnviar;

    public ValidacionTiempoReal() {
        setTitle("Validacion en tiempo real");
        setSize(400, 150);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        JPanel panel = new JPanel(new GridLayout(3, 2, 5, 5));
        panel.setBorder(BorderFactory.createEmptyBorder(10, 20, 10, 20));

        campoEmail = new JTextField();
        lblEstado = new JLabel("Introduce tu email");
        lblEstado.setForeground(Color.GRAY);
        btnEnviar = new JButton("Enviar");
        btnEnviar.setEnabled(false); // Deshabilitado por defecto

        panel.add(new JLabel("Email:"));
        panel.add(campoEmail);
        panel.add(new JLabel("Estado:"));
        panel.add(lblEstado);
        panel.add(new JLabel(""));
        panel.add(btnEnviar);

        // Validar en tiempo real con DocumentListener
        campoEmail.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) { validar(); }
            @Override
            public void removeUpdate(DocumentEvent e) { validar(); }
            @Override
            public void changedUpdate(DocumentEvent e) { validar(); }
        });

        // Accion del boton
        btnEnviar.addActionListener(e -> {
            JOptionPane.showMessageDialog(this,
                "Email enviado: " + campoEmail.getText());
        });

        add(panel);
    }

    private void validar() {
        String email = campoEmail.getText().trim();
        if (email.isEmpty()) {
            lblEstado.setText("Introduce tu email");
            lblEstado.setForeground(Color.GRAY);
            btnEnviar.setEnabled(false);
        } else if (email.contains("@") && email.contains(".")) {
            lblEstado.setText("Email valido");
            lblEstado.setForeground(new Color(0, 128, 0));
            btnEnviar.setEnabled(true);
        } else {
            lblEstado.setText("Email no valido");
            lblEstado.setForeground(Color.RED);
            btnEnviar.setEnabled(false);
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new ValidacionTiempoReal().setVisible(true));
    }
}

