import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import javax.swing.Timer;

public class Cronometro extends JFrame {
    private int segundos = 0;
    private boolean corriendo = false;
    private JLabel lblTiempo, lblEstado;
    private Timer timer;

    public Cronometro() {
        setTitle("Cronometro");
        setSize(300, 150);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        lblTiempo = new JLabel("00:00");
        lblTiempo.setFont(new Font("Monospaced", Font.BOLD, 36));
        lblEstado = new JLabel("Pulsar E para iniciar", SwingConstants.CENTER);

        JPanel panel = new JPanel();
        panel.add(lblTiempo);
        panel.add(lblEstado);
        add(panel);

        timer = new Timer(1000, e -> {
            segundos++;
            int min = segundos / 60;
            int seg = segundos % 60;
            lblTiempo.setText(String.format("%02d:%02d", min, seg));
        });

        addKeyListener(new KeyAdapter() {
            @Override
            public void keyReleased(KeyEvent e) {
                switch (Character.toLowerCase(e.getKeyChar())) {
                    case 'e' -> {
                        timer.start();
                        corriendo = true;
                        lblEstado.setText("Corriendo (P=pause, R=reset)");
                    }
                    case 'p' -> {
                        timer.stop();
                        corriendo = false;
                        lblEstado.setText("Pausado (E=reanudar)");
                    }
                    case 'r' -> {
                        timer.stop();
                        segundos = 0;
                        corriendo = false;
                        lblTiempo.setText("00:00");
                        lblEstado.setText("Reiniciado (E=iniciar)");
                    }
                }
            }
        });

        setFocusable(true);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new Cronometro().setVisible(true));
    }
}

