        principal.setBorder(BorderFactory.createEmptyBorder(15, 15, 15, 15));

        // === NORTE: Titulo ===
        JLabel titulo = new JLabel("Calculadora", SwingConstants.CENTER);
        titulo.setFont(new Font("Arial", Font.BOLD, 20));
        principal.add(titulo, BorderLayout.NORTH);

        // === CENTRO: Formulario ===
        JPanel formulario = new JPanel(new GridLayout(4, 2, 8, 8));

        campo1 = new JTextField();
        campo2 = new JTextField();
        comboOp = new JComboBox<>(new String[]{"Sumar (+)", "Restar (-)", "Multiplicar (*)", "Dividir (/)"});
        resultado = new JLabel("Resultado: ");
        resultado.setFont(new Font("Monospaced", Font.BOLD, 16));

        formulario.add(new JLabel("Numero 1:"));
        formulario.add(campo1);
        formulario.add(new JLabel("Operacion:"));
        formulario.add(comboOp);
        formulario.add(new JLabel("Numero 2:"));
        formulario.add(campo2);
        formulario.add(new JButton("Calcular"));
        formulario.add(resultado);

        principal.add(formulario, BorderLayout.CENTER);

        // Evento del boton
        JButton btnCalcular = (JButton) formulario.getComponent(6);
        btnCalcular.addActionListener(e -> calcular());

        // === SUR: Creditos ===
        JLabel creditos = new JLabel("Calculadora v1.0 - Java Swing", SwingConstants.CENTER);
        creditos.setForeground(Color.GRAY);
        principal.add(creditos, BorderLayout.SOUTH);

        add(principal);
    }

    private void calcular() {
        // Validacion
        String texto1 = campo1.getText().trim();
        String texto2 = campo2.getText().trim();

        if (texto1.isEmpty() || texto2.isEmpty()) {
            resultado.setText("Error: introduce ambos numeros");
            resultado.setForeground(Color.RED);
            return;
        }

        double a, b;
        try {
            a = Double.parseDouble(texto1);
            b = Double.parseDouble(texto2);
        } catch (NumberFormatException ex) {
            resultado.setText("Error: valores numericos invalidos");
            resultado.setForeground(Color.RED);
            return;
        }

        // Operacion
        String op = (String) comboOp.getSelectedItem();
        double res;
        if (op.startsWith("Sumar")) {
            res = a + b;
        } else if (op.startsWith("Restar")) {
            res = a - b;
        } else if (op.startsWith("Multiplicar")) {
            res = a * b;
        } else {
            if (b == 0) {
                resultado.setText("Error: division por cero");
                resultado.setForeground(Color.RED);
                return;
            }
            res = a / b;
        }

        // Mostrar resultado
        resultado.setForeground(new Color(0, 100, 0));
        resultado.setText(String.format("Resultado: %.4f", res));
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new CalculadoraGUI().setVisible(true));
    }
}

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Gestion de alumnos con interfaz grafica.
 * Incluye: formulario, validacion, lista, y estado.
 */
public class GestorAlumnosGUI extends JFrame {

    private JTextField campoNombre, campoEmail, campoEdad;
    private DefaultListModel<String> modeloLista;
    private JList<String> listaAlumnos;
    private JLabel lblEstado, lblTotal;
    private final List<String> alumnos = new ArrayList<>();

    public GestorAlumnosGUI() {
        setTitle("Gestor de Alumnos");
        setSize(550, 420);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLocationRelativeTo(null);

        JPanel principal = new JPanel(new BorderLayout(10, 10));
        principal.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        // NORTE: Titulo + estadisticas
        JPanel norte = new JPanel(new BorderLayout());
        JLabel titulo = new JLabel("Gestor de Alumnos", SwingConstants.CENTER);
        titulo.setFont(new Font("Arial", Font.BOLD, 18));
        norte.add(titulo, BorderLayout.NORTH);
        lblTotal = new JLabel("Total: 0 alumnos", SwingConstants.CENTER);
        lblTotal.setForeground(Color.GRAY);
        norte.add(lblTotal, BorderLayout.SOUTH);
        principal.add(norte, BorderLayout.NORTH);

        // CENTRO: Formulario + Lista
        JPanel centro = new JPanel(new BorderLayout(10, 10));

        JPanel formulario = new JPanel(new GridLayout(4, 2, 5, 5));
        campoNombre = new JTextField();
        campoEmail = new JTextField();
        campoEdad = new JTextField();

        formulario.add(new JLabel("Nombre:"));
        formulario.add(campoNombre);
        formulario.add(new JLabel("Email:"));
        formulario.add(campoEmail);
        formulario.add(new JLabel("Edad:"));
        formulario.add(campoEdad);

        JPanel botones = new JPanel(new FlowLayout());
        JButton btnAgregar = new JButton("Agregar");
        JButton btnLimpiar = new JButton("Limpiar");
        JButton btnEliminar = new JButton("Eliminar seleccion");
        botones.add(btnAgregar);
        botones.add(btnLimpiar);
        botones.add(btnEliminar);
        formulario.add(botones);

        centro.add(formulario, BorderLayout.NORTH);

        modeloLista = new DefaultListModel<>();
        listaAlumnos = new JList<>(modeloLista);
        listaAlumnos.setFont(new Font("Monospaced", Font.PLAIN, 12));
        centro.add(new JScrollPane(listaAlumnos), BorderLayout.CENTER);

        principal.add(centro, BorderLayout.CENTER);

        // SUR: Estado
        lblEstado = new JLabel("Listo", SwingConstants.CENTER);
        lblEstado.setBorder(BorderFactory.createEtchedBorder());
        principal.add(lblEstado, BorderLayout.SOUTH);

        // EVENTOS
        btnAgregar.addActionListener(e -> agregarAlumno());
        btnLimpiar.addActionListener(e -> limpiarCampos());
        btnEliminar.addActionListener(e -> eliminarSeleccion());

        add(principal);
    }

    private void agregarAlumno() {
        String nombre = campoNombre.getText().trim();
        String email = campoEmail.getText().trim();
        String edad = campoEdad.getText().trim();

        if (nombre.isEmpty() || email.isEmpty()) {
            mostrarError("Nombre y email son obligatorios.");
            return;
        }
        if (!email.contains("@")) {
            mostrarError("El email no es valido.");
            return;
        }
        try {
            Integer.parseInt(edad);
        } catch (NumberFormatException ex) {
            mostrarError("La edad debe ser un numero entero.");
            return;
        }

        String alumno = String.format("%-20s %-25s %3s", nombre, email, edad);
        alumnos.add(alumno);
        modeloLista.addElement(alumno);

        lblTotal.setText("Total: " + alumnos.size() + " alumnos");
        lblEstado.setText("Alumno agregado: " + nombre);
        lblEstado.setForeground(new Color(0, 100, 0));
        limpiarCampos();
    }

    private void limpiarCampos() {
        campoNombre.setText("");
        campoEmail.setText("");
        campoEdad.setText("");
        campoNombre.requestFocus();
    }

    private void eliminarSeleccion() {
        int idx = listaAlumnos.getSelectedIndex();
        if (idx == -1) {
            mostrarError("Selecciona un alumno para eliminar.");
            return;
        }
        String eliminado = alumnos.remove(idx);
        modeloLista.remove(idx);
        lblTotal.setText("Total: " + alumnos.size() + " alumnos");
        lblEstado.setText("Eliminado: " + eliminado.trim());
        lblEstado.setForeground(Color.RED);
    }

    private void mostrarError(String msg) {
        lblEstado.setText("Error: " + msg);
        lblEstado.setForeground(Color.RED);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new GestorAlumnosGUI().setVisible(true));
    }
}

